const ctx=vm.createContext({Math,JSON,console:{...console,error(...args){errors.push(args.map(String).join(" "));}},structuredClone,TextEncoder,TextDecoder,performance,setTimeout:()=>1,clearTimeout(){},requestAnimationFrame:()=>1,cancelAnimationFrame(){},addEventListener(name,fn){rootListeners[name]=fn;},scrollTo(){},matchMedia:()=>({matches:true}),localStorage:{getItem:k=>disk.get(k)??null,setItem(k,v){if(quota||(backupOnly&&k.endsWith('_backup')))throw Object.assign(Error('full'),{name:'QuotaExceededError'});disk.set(k,v)},removeItem(k){disk.delete(k)}}});
