const source=(inline?inline[names.indexOf('script')]:read('src/script.js')).replace('root.KM_APP={','root.QA121={actions,render,save,ui,detail139,progressDecision144,progressBar144,confirm:()=>confirmCallback,renderId:()=>renderId,suspend139,openModal,closeModal,slotStore,opportunity134,rivalMemory134,journeyJournal134,resultView,mentorView,mentorIntroductionPanel125,epiloguePanel126,novelContext,supportPanel121,startPolicyPanel118,helpView,openNovel,tiltPanel131,novel:()=>novelCurrent,replay:()=>replayRace,prepHub121,entryOptions,recordPractice122,practiceStore:()=>practiceRecords122,load(s,page){state=s;ui.page=page;render();},current:()=>state};root.KM_APP={');
