const Q=ctx.QA121,E=ctx.KM_ENGINE,html=()=>(nodes.app.innerHTML+(nodes.modal.hidden?'':nodes.modal.innerHTML)).replace(/data:(?:image|audio)\/[^;]+;base64,[^"']*/g,'data:asset');
function preserve(before,after,at='career'){if(at==='career'){before=E.clone(before);E.Bonds.ensure(before);E.Drama.rivalState(before);}if(before===null||typeof before!=='object'){assert.equal(after,before,at);return;}if(Array.isArray(before))assert.equal(after.length,before.length,at);for(const key of Object.keys(before))preserve(before[key],after[key],at+'.'+key);}
function test(name,fn){console.log('RUN '+name);try{const at=errors.length;fn();assert.equal(errors.length,at,errors.slice(at).join('\n'));report.checks.push(name);}catch(e){report.failures||=[];report.failures.push({name,error:e.message});}}
function career(arc='light',seed=121,mode='normal'){const s=E.newState(seed),p=E.character(s,'画面検証');p.scenario=arc;p.difficulty=mode;E.createCareer(s,p);return s}
function finishPage(){const sc=Q.novel();assert.ok(sc);for(let n=0;n<250&&Q.novel()===sc;n++)Q.actions.novelNext();}
function toLast(){for(let n=0;n<250&&Q.novel()&&Q.novel().index<Q.novel().pages.length-1;n++)Q.actions.novelNext();}
function drain(limit=30){const kinds=[];for(let n=0;n<limit&&Q.ui.page==='novel';n++){const c=Q.current().career;assert.ok(c.flow131?.active,'auto scene ownership');kinds.push(c.flow131.active.kind);toLast();const sc=Q.novel();if(sc.choices?.length){const ch=sc.choices.find(x=>!x.disabled);Q.actions[ch.action](String(ch.value));}else Q.actions.novelNext();assert.ok(E.validState(Q.current()),JSON.stringify(c.flow131));}assert.notEqual(Q.ui.page,'novel','queue eventually returns');return kinds;}
function meet(c,id){Object.assign(c.bonds.heroines[id],{met:true,metStage:0,metRace:0});}

// Dispatch the actual document listeners using buttons found in rendered markup.
function click(action,value,{moved=false,detail=1}={}){
 const tags=[...html().matchAll(/<button\b[^>]*>/g)].map(m=>m[0]);
 const tag=tags.find(t=>t.includes('data-action="'+action+'"')&&(value===undefined||t.includes('data-value="'+value+'"')));
 assert.ok(tag,'rendered button '+action+' '+(value??''));
 const node={isConnected:true,disabled:/ disabled(?:[ >]|$)/.test(tag),dataset:{action,view144:tag.match(/data-view144="([^"]*)"/)?.[1],target144:tag.match(/data-target144="([^"]*)"/)?.[1]?.replace(/&quot;/g,'"').replace(/&amp;/g,'&').replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>'),help139:tag.match(/data-help139="([^"]*)"/)?.[1],value:tag.match(/data-value="([^"]*)"/)?.[1]||''}};
 const stage=Q.novel()?{}:null,target={closest(s){return s==='[data-action]'?node:s==='.novel-stage'?stage:s==='#modal'?(nodes.modal.hidden?null:node):node;}};
 listeners.pointerdown({target,clientX:20,clientY:20});
 if(moved)listeners.pointermove({clientX:40,clientY:20});
 listeners.click({target,detail});
}
function lastClick(){for(let n=0;n<300&&Q.novel()&&Q.novel().index<Q.novel().pages.length-1;n++)click('novelNext');assert.equal(Q.novel().index,Q.novel().pages.length-1);}
function drainClicks(limit=60){for(let n=0;n<limit&&Q.novel();n++){lastClick();const sc=Q.novel(),ch=sc.choices?.find(x=>!x.disabled);click(ch?ch.action:'novelNext',ch?String(ch.value):undefined);}assert.equal(Q.novel(),null,'reader eventually closes');}
function ready(page='action',stage=0){const s=career();s.career.stage=stage;s.career.stats.races=stage*6;Q.load(s,'home');drainClicks();if(page!=='home'){click('series');drainClicks();if(page==='action'){click('prepare');drainClicks();}}return s;}
