function pointerNode(action,value){const tags=[...html().matchAll(/<button\b[^>]*>/g)].map(m=>m[0]),tag=tags.find(t=>t.includes('data-action="'+action+'"')&&(value===undefined||t.includes('data-value="'+value+'"')));assert.ok(tag,'button '+action+' '+value);const node={isConnected:true,disabled:/ disabled(?:[ >]|$)/.test(tag),dataset:{action,view144:tag.match(/data-view144="([^"]*)"/)?.[1],target144:tag.match(/data-target144="([^"]*)"/)?.[1]?.replace(/&quot;/g,'"').replace(/&amp;/g,'&').replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>'),value:tag.match(/data-value="([^"]*)"/)?.[1]||'',help139:tag.match(/data-help139="([^"]*)"/)?.[1]}};return {node,target:{closest(q){return q==='[data-action]'||q==='[data-help139]'?node:q==='#modal'?(nodes.modal.hidden?null:node):null;}}};}
function timers139(fn){const old=[ctx.setTimeout,ctx.clearTimeout],jobs=new Map();let id=0;ctx.setTimeout=(fn,ms)=>{jobs.set(++id,{fn,ms});return id;};ctx.clearTimeout=id=>jobs.delete(id);try{fn(jobs);}finally{ctx.setTimeout=old[0];ctx.clearTimeout=old[1];}}
test('練習の長押しは説明だけを開き、指を離したクリックで回数や能力を変えない',()=>{const s=ready(),before=snapshot(s.career);timers139(jobs=>{const {node,target}=pointerNode('train','speed');listeners.pointerdown({target,clientX:10,clientY:10});const hold=[...jobs.values()].find(j=>j.ms===550);assert.ok(hold);hold.fn();assert.equal(nodes.modal.hidden,false);assert.match(nodes.modal.innerHTML,/直線の練習/);listeners.pointerup({target});listeners.click({target,detail:1,preventDefault(){}});assert.equal(snapshot(s.career),before);Q.actions.closeModal();assert.equal(nodes.modal.hidden,true);});});
