function momentFixture142(){const s=ready(),c=s.career;meet(c,'akari');const q=c.bonds.heroines.akari;for(let i=0;i<2;i++){q.trust=q.affection=100;c.stats.races=Math.max(c.stats.races,c.bonds.nextAt,i*2);const p=E.Bonds.open(c,'akari');assert.ok(p);const sc=E.Bonds.scene(c);assert.ok(E.chooseBond(c,p.key,sc.choices.findIndex(x=>x.code===0)));const request=E.Affinity.offer(c);if(request)E.Affinity.reply(c,request.id,1);}c.stats.races=E.Continuity142.moment(c,'akari',2).due;const f=E.Flow.ensure(c);f.visited=[];f.queue=[];f.active=null;return s;}
