test('前走の次へボタンは新しい結果画面でも実行されない',()=>{const s=result141(),old=pointerNode('nextRace');click('nextRace');drainClicks();click('pre');E.skipToResult(s);Q.load(s,'raceResult');const before=snapshot(s.career);listeners.click({target:old.target,detail:0});assert.equal(snapshot(s.career),before);assert.equal(Q.ui.page,'raceResult');click('nextRace');drainClicks();assert.equal(Q.ui.page,'action');});
