function finishBatches144(jobs){for(let i=0;Q.ui.resolving&&i<500;i++){const batch=[...jobs.entries()].find(([,j])=>j.fn.name==='batch');assert.ok(batch,'queued calculation');jobs.delete(batch[0]);batch[1].fn();}assert.equal(Q.ui.resolving,false);}
test('育成の手動必須決勝と同時でも大会の観戦から結果スキップでき、育成は変えない',()=>{const s=ready(),c=s.career;c.series.race.type='championship';c.series.race.finalSpectator141=false;const p=E.character(s,'大会スキップ');s.registry=[p];E.After143.start(s,[p.id],p.id,'sprint',E);Q.actions.cup143();click('cupRace143','auto');const before=JSON.stringify(c);timers139(jobs=>{assert.equal(Q.progressDecision144('instantRace').allowed,true);click('instantRace');assert.equal(Q.ui.resolving,true);finishBatches144(jobs);});assert.equal(s.quick.race.done,true);assert.equal(s.cup143.results.length,1);assert.equal(Q.ui.page,'quickResult');assert.equal(JSON.stringify(c),before);Q.actions.registry();});
test('育成がない展示レースでも観戦のスキップと結果再表示が使える',()=>{const s=E.newState(9144);s.registry=Array.from({length:6},(_,i)=>E.character(s,'展示 '+i));E.quickRace(s,s.registry.map(p=>p.id));Q.ui.quick=true;E.prepareSpectator(s,true);Q.load(s,'race');timers139(jobs=>{click('instantRace');assert.equal(Q.ui.resolving,true);finishBatches144(jobs);});assert.equal(s.career,null);assert.equal(s.quick.race.done,true);assert.equal(Q.ui.page,'quickResult');s.quick.race.watch=true;Q.load(s,'race');click('result');assert.equal(Q.ui.page,'quickResult');assert.ok(E.validState(s));Q.actions.registry();});

