function setupChallenge145(mode='auto'){const s=ready(),p=E.character(s,'固定の選手');p.skills=['quick'];s.registry=[p];Q.actions.registry();click('challenge145');nodes['challenge-driver145']={value:p.id};nodes['challenge-mode145']={value:mode};return s;}
