function decodedDiagnostic146(){return JSON.parse(nodes.modal.innerHTML.match(/<textarea id="diagnostic146-text"[^>]*>([\s\S]*?)<\/textarea>/)[1].replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&'));}
test('通常診断には人物名・会話全文がなく、直近の主操作と画面を残す',()=>{const s=ready();s.career.player.name='PRIVATE_PLAYER_146';s.career.campaign.entries[0].prose.body.push('PRIVATE_DIALOGUE_146');Q.actions.data();const before=JSON.stringify(s);click('diagnostic146');const d=decodedDiagnostic146();assert.equal(d.build,'147');assert.equal(d.screen,'data');assert.equal(d.recent.at(-1).action,'diagnostic146');assert.doesNotMatch(JSON.stringify(d),/PRIVATE_PLAYER_146|PRIVATE_DIALOGUE_146/);assert.equal(JSON.stringify(s),before);Q.actions.closeModal();});
test('診断は実際の主保存失敗と別保存先だけの失敗を分ける',()=>{ready();Q.actions.data();quota=true;Q.save();click('diagnostic146');assert.equal(decodedDiagnostic146().storage.main,'not-durable');assert.ok(decodedDiagnostic146().storage.failureKinds.includes('capacity'));Q.actions.closeModal();quota=false;Q.actions.retrySave();backupOnly=true;Q.current().coins++;Q.save();click('diagnostic146');assert.equal(decodedDiagnostic146().storage.main,'saved');assert.equal(decodedDiagnostic146().storage.otherPending,true);Q.actions.closeModal();backupOnly=false;Q.actions.retrySave();});
test('失敗したJSON読込は診断に型だけを残し、進行を置き換えない',()=>{ready();Q.actions.data();nodes['import-text']={value:'PRIVATE_INVALID_JSON_146'};const before=JSON.stringify(Q.current());click('import');click('diagnostic146');const d=decodedDiagnostic146();assert.equal(d.errors.at(-1).scope,'import');assert.equal(d.errors.at(-1).type,'SyntaxError');assert.doesNotMatch(JSON.stringify(d),/PRIVATE_INVALID_JSON_146/);assert.equal(JSON.stringify(Q.current()),before);Q.actions.closeModal();});
