async function testAsync146(name,fn){try{await fn();report.checks.push(name)}catch(e){report.failures||=[];report.failures.push({name,error:e.stack})}}
(async()=>{
await testAsync146('非同期エラーも操作ハンドラーで受け止め、復帰と診断の入口を示す',async()=>{Q.load(career(),'title');const original=Q.actions.support146;Q.actions.support146=()=>Promise.reject(new RangeError('PRIVATE_ASYNC_146'));try{click('support146');await Promise.resolve();assert.match(html(),/進行を確認してください/);click('diagnostic146');const d=decodedDiagnostic146();assert.equal(d.errors.at(-1).scope,'async');assert.equal(d.errors.at(-1).type,'RangeError');assert.doesNotMatch(JSON.stringify(d),/PRIVATE_ASYNC_146/);}finally{Q.actions.support146=original;Q.actions.closeModal();}});
await testAsync146('診断コピーの成功・利用不可の手動選択と、診断だけのダウンロードを確認',async()=>{Q.load(career(),'title');Q.actions.diagnostic146();const d=decodedDiagnostic146();let selected=0,copied=null,downloaded=null;nodes['diagnostic146-text']={value:JSON.stringify(d),focus(){},select(){selected++}};ctx.navigator={clipboard:{writeText:async x=>{copied=x}}};await Q.actions.diagnosticCopy146();assert.equal(copied,JSON.stringify(d));ctx.navigator={};await Q.actions.diagnosticCopy146();assert.equal(selected,1);const oldCreate=ctx.document.createElement,oldAppend=ctx.document.body.appendChild;ctx.Blob=class{constructor(parts){this.text=parts.join('')}};ctx.URL={createObjectURL(blob){downloaded=blob.text;return 'blob:test'},revokeObjectURL(){}};ctx.document.createElement=()=>({click(){},remove(){}});ctx.document.body.appendChild=()=>{};try{click('diagnosticDownload146');assert.equal(downloaded,JSON.stringify(d));assert.doesNotMatch(downloaded,/"career":\s*\{|"player"|"registry":/);}finally{ctx.document.createElement=oldCreate;ctx.document.body.appendChild=oldAppend;Q.actions.closeModal();}});
await testAsync146('確認してから書き出すセーブJSONは完全データで、通常診断とは別に渡す',async()=>{Q.load(career(),'title');let shared=null;const oldIphone=ctx.KM_IPHONE;ctx.KM_IPHONE={shareBackup:async text=>{shared=text;return 'shared'}};try{Q.actions.diagnostic146();click('diagnosticSave146');assert.equal(shared,null);await Q.actions.confirm();assert.ok(JSON.parse(shared).career.player.name);assert.equal(JSON.parse(shared).build,'147');assert.ok(E.validState(JSON.parse(shared)));}finally{ctx.KM_IPHONE=oldIphone;}});

fs.writeFileSync(path.join(__dirname,process.env.REPRO139?'repro-before-v140.json':(process.env.REPORT139||'progress-v147.json')),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report));if(report.failures?.length)process.exitCode=1;

})();
